alter table public.orders add column if not exists whatsapp_consent boolean not null default false;
create or replace function public.snapshot_order_exchange_rate() returns trigger language plpgsql security definer set search_path='public' as $$ declare v_rate numeric; begin if new.exchange_rate is null then select nullif(value->>'exchange_rate','')::numeric into v_rate from public.store_settings where key='commerce'; new.exchange_rate:=coalesce(v_rate,135); end if; return new; end $$;
drop trigger if exists orders_snapshot_exchange_rate on public.orders;
create trigger orders_snapshot_exchange_rate before insert on public.orders for each row execute function public.snapshot_order_exchange_rate();
create or replace function public.enqueue_order_whatsapp() returns trigger language plpgsql security definer set search_path='public' as $$ declare v_enabled boolean:=false; begin select coalesce(value->>'whatsapp_enabled','false')::boolean into v_enabled from public.store_settings where key='notifications'; if v_enabled and new.whatsapp_consent and (tg_op='INSERT' or old.status is distinct from new.status) then insert into public.notifications(order_id,channel,recipient,template_name,idempotency_key,payload) values(new.id,'whatsapp',new.phone,'order_'||new.status::text,new.id::text||':'||new.status::text,jsonb_build_object('order_number',new.order_number,'customer_name',new.customer_name,'total',new.total,'currency',new.currency,'status',new.status,'subtotal',new.subtotal,'shipping_fee',new.shipping_fee,'delivery_address',new.delivery_address)) on conflict (idempotency_key) where idempotency_key is not null do nothing; end if; return new; end $$;
drop trigger if exists orders_enqueue_whatsapp on public.orders;
create trigger orders_enqueue_whatsapp after insert or update of status on public.orders for each row execute function public.enqueue_order_whatsapp();
